a:ZMicromega;?~~~~~~~~~~~~~~~K47Corelib4Init9Datatypes3nat01I47Corelib4Init9Datatypes3nat00C56Stdlib5Arith8PeanoNat3Nat3addC56Stdlib6ZArith4Znat5Nat2Z7inj_addI59OSSVerify5KrLib6Common8KXBridge4zexp00C1?~~~~~~~~~~~~~~~I69OSSVerify5KrLib6Common6KXExec3KX24expr00C1?~~~~~~~~~~~~~~~K4ELinuxProcessSemantics5Riscv5Instr5aluop01K4ELinuxProcessSemantics5Riscv5Instr5mulop01K47Corelib4Init9Datatypes4bool02I47Corelib4Init5Logic5False00C4ELinuxProcessSemantics5Riscv3Sem2w0K4ELinuxProcessSemantics5Riscv5Instr5aluop07K4ELinuxProcessSemantics5Riscv5Instr5aluop0:I69OSSVerify5KrLib6Common6KXExec3KX26sentry00C1?~~~~~~~~~~~~~~~I69OSSVerify5KrLib6Common6KXExec3KX28sidecond00C1?~~~~~~~~~~~~~~~K4ELinuxProcessSemantics5Riscv5Instr;branch_cond03K4ELinuxProcessSemantics5Riscv5Instr5aluop02I47Corelib4Init5Logic4True00K47Corelib4Init5Logic4True01I4ELinuxProcessSemantics?LinuxProcessSem>RiscvSemantics=machine_state00C59OSSVerify5KrLib4LibA5ExecF9footprintC1?~~~~~~~~~~~~~~~K47Corelib7Numbers7BinNums8positive03I46Stdlib5Lists4List6Exists00I47Corelib4Init9Datatypes:comparison00C46Stdlib9micromega8ZifyInst7Inj_Z_ZI69OSSVerify5KrLib6Common6KXExec3KX23env00C1?~~~~~~~~~~~~~~~I69OSSVerify5KrLib6Common6KXExec3KX29sym_state00C1?~~~~~~~~~~~~~~~I69OSSVerify5KrLib6Common6KXExec3KX27scripts00C1?~~~~~~~~~~~~~~~C59OSSVerify5KrLib3Lib5Frame3ivlC1?~~~~~~~~~~~~~~~K4ELinuxProcessSemantics5Riscv5Instr5aluop05c59OSSVerify5KrLib5AsanW<AF_huf_z4s1d=z4s1_s34_caseC1?~~~~~~~~~~~~~~~".
Import ListNotations. Import KXS.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Set Warnings "-notation-for-abbreviation".
Notation amem := (word -> option byte).
Notation zlen l := (Z.of_nat (length l)).

Definition z4s1_s34_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (gp tp m15 m16 y1 y8 y10 y11 y13 y14 y15 y17 y19 y21 y22 y25 y26 y29 y31 c4 k6 k9 k16 k20 k23 k24 : word)
         (SPF SS n SBL SBH l1 l2 l3 pt3 pt4 PTR3 PTR4 P3 P4 tl : Z),
    PTR3 = SS + 6 + l1 + l2 + pt3 -> PTR4 = SS + 6 + l1 + l2 + l3 + pt4 ->
    z4s_src_ctx RNG mm SS n SBL SBH -> n < 2^26 ->
    rw_cells asegs mm (SPF + 232) [C8 (Z_to_bv 64 (SS + 6 + l1 + l2 + l3 + 8))] ->
    rw_cells asegs mm (SPF + 264) [C8 (Z_to_bv 64 (SS + 6 + l1 + l2 + 8))] ->
    rw_cells asegs mm (SPF + 288) [C8 (Z_to_bv 64 PTR3)] ->
    rw_cells asegs mm (SPF + 296) [C8 c4] -> rw_cells asegs mm (SPF + 320) [C8 c4] ->
    rw_cells asegs mm (SPF + 336) [C8 (Z_to_bv 64 PTR4)] ->
    rng RNG SPF 576 -> 0x10007fff8000 <= SPF -> SPF + 576 <= 2^47 -> KXGoM.apart SS n SPF 576 ->
    1 <= l1 -> 1 <= l2 -> 1 <= l3 -> 6 + l1 + l2 + l3 + 1 <= n ->
    0 <= pt3 -> (pt3 = 0 \/ pt3 + 8 <= l3) -> 0 <= pt4 -> (pt4 = 0 \/ pt4 + 8 <= n - (6 + l1 + l2 + l3)) ->
    0 <= P3 <= 100 -> 0 <= P4 <= 100 -> (8 <= pt3 -> P3 <= 44) -> (8 <= pt4 -> P4 <= 44) ->
    0 <= bv_unsigned m15 <= 12 -> 0 <= bv_unsigned m16 <= 12 ->
    (forall (mm' : amem) (PT3 PT4 ST3 ST4 : Z) (b3w b4w c3' c4' j5 j9 j16 j20 j23 j24 j29 : word),
       munch [(SPF + 288, SPF + 304); (SPF + 320, SPF + 328); (SPF + 336, SPF + 344)] mm mm' -> wmono asegs mm mm' ->
       mem_inv asegs mm' ->
       rw_cells asegs mm' (SPF + 288) [C8 (Z_to_bv 64 PT3)] -> rw_cells asegs mm' (SPF + 296) [C8 c4'] ->
       rw_cells asegs mm' (SPF + 320) [C8 c4'] -> rw_cells asegs mm' (SPF + 336) [C8 (Z_to_bv 64 PT4)] ->
       z1rel l3 (PT3 - (SS + 6 + l1 + l2)) (bv_unsigned b3w) ST3 ->
       z1rel (n - (6 + l1 + l2 + l3)) (PT4 - (SS + 6 + l1 + l2 + l3)) (bv_unsigned b4w) ST4 ->
       evtF asegs RNG Q (MS (mkR y19 (Z_to_bv 64 SPF) gp tp j5 (Z_to_bv 64 ST4) (Z_to_bv 64 ST3) y8 j9 y10 y11
                                 (Z_to_bv 64 PT4) y13 y14 y15 j16 y17 b3w c3' j20 y21 y22 j23 j24 y25 y26
                                 (Z_to_bv 64 2147450880) (Z_to_bv 64 (64 - tl)) j29 b4w y31)
                            F (Z_to_bv 64 0x89384) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR y1 (Z_to_bv 64 SPF) gp tp m16 k6 m15 y8 k9 y10 y11 (Z_to_bv 64 PTR4)
                             y13 y14 y15 k16 y17 (Z_to_bv 64 P3) y19 k20 y21 y22 k23 k24 y25 y26 (Z_to_bv 64 2147450880)
                             (Z_to_bv 64 (64 - tl)) y29 (Z_to_bv 64 P4) y31)
                        F (Z_to_bv 64 0x8922c) fc None mm (seg_rom asegs)).

Ltac z4s34_post K F288 F296 F320 F336 SPF mm :=
  kx_post_regs_keep;
  let MU := fresh "MU" in let WM := fresh "WM" in
  pose proof (munch_refl [(SPF + 288, SPF + 304); (SPF + 320, SPF + 328); (SPF + 336, SPF + 344)] mm) as MU;
  pose proof (wmono_refl asegs mm) as WM;
  kx_munch_wins MU [(SPF + 288, 16); (SPF + 320, 8); (SPF + 336, 8)];
  (first [ kx_cellz F288 | (kx_frame F288; try (cbn [cells_size csize]; lia)) ]);
  (first [ kx_cellw F296 | (kx_frame F296; try (cbn [cells_size csize]; lia)) ]);
  (first [ kx_cellw F320 | (kx_frame F320; try (cbn [cells_size csize]; lia)) ]);
  (first [ kx_cellz F336 | (kx_frame F336; try (cbn [cells_size csize]; lia)) ]);
  kx_post_mem_free;
